import {build} from 'esbuild';
import {readFile,writeFile} from 'node:fs/promises';
const root=new URL('../',import.meta.url),path=new URL('extension/auth-worker.js',root);
const result=await build({absWorkingDir:root.pathname.replace(/^\/(\w:)/,'$1'),entryPoints:['extension/auth/index.mjs'],bundle:true,format:'iife',globalName:'YPAuth',platform:'browser',target:['chrome140','firefox142'],minify:true,write:false,legalComments:'none'});
const generated='// Generated by scripts/extension-auth-bundle.mjs; edit extension/auth/session.mjs.\n'+result.outputFiles[0].text;
if(process.argv.includes('--check')){if(await readFile(path,'utf8')!==generated)throw Error('Auth bundle drift');}else await writeFile(path,generated);
console.log('Worker-only auth bundle verified.');
